//! Published known-answer vectors; no expected digest is generated by this port.
//! FIPS 180-4 / 197, SP 800-38A, RFC 2202 / 4231 / 6070.
use aes::cipher::{BlockCipherDecrypt, BlockCipherEncrypt, KeyInit, KeyIvInit, StreamCipher};
use hex_literal::hex;
use hmac::Mac;
use tg_base::openssl_help::*;

#[test]
fn fips_sha_abc_and_million_a() {
    assert_eq!(
        sha1(b"abc"),
        hex!("a9993e364706816aba3e25717850c26c9cd0d89d")
    );
    assert_eq!(
        sha256(b"abc"),
        hex!("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
    );
    assert_eq!(sha512(b"abc"), hex!("ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192 992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f"));
    let a = vec![b'a'; 1_000_000];
    assert_eq!(sha1(&a), hex!("34aa973cd4c4daa4f61eeb2bdbad27316534016f"));
    assert_eq!(
        sha256(&a),
        hex!("cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0")
    );
    assert_eq!(sha512(&a), hex!("e718483d0ce769644e2e42c7bc15b4638e1f98b13b2044285632a803afa973eb de0ff244877ea60a4cb0432ce577c31beb009c5c2c49aa2e4eadb217ad8cc09b"));
    let parts: &[&[u8]] = &[b"a", b"", b"bc"];
    assert_eq!(sha1_parts(parts), sha1(b"abc"));
    assert_eq!(sha256_parts(parts), sha256(b"abc"));
    assert_eq!(sha512_parts(parts), sha512(b"abc"));
    let mut dst = [0x5a; 70];
    sha512_to(&mut dst, b"abc");
    assert_eq!(&dst[..64], sha512(b"abc"));
    assert_eq!(&dst[64..], &[0x5a; 6]);
}

#[test]
fn rfc_hmac() {
    // RFC 2202 case 1: legacy SHA1 used outside this wrapper in storage.
    let mut mac = <hmac::Hmac<sha1::Sha1> as hmac::KeyInit>::new_from_slice(&[0x0b; 20]).unwrap();
    mac.update(b"Hi There");
    assert_eq!(
        &mac.finalize().into_bytes()[..],
        hex!("b617318655057264e28bc0b6fb378c8ef146be00")
    );
    // RFC 4231 cases 1, 2, 6 (key longer than the hash block).
    assert_eq!(
        hmac_sha256(&[0x0b; 20], b"Hi There"),
        hex!("b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7")
    );
    assert_eq!(
        hmac_sha256(b"Jefe", b"what do ya want for nothing?"),
        hex!("5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843")
    );
    assert_eq!(
        hmac_sha256(
            &[0xaa; 131],
            b"Test Using Larger Than Block-Size Key - Hash Key First"
        ),
        hex!("60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54")
    );
}

#[test]
fn pbkdf2_reference_vectors() {
    for (iterations, expected) in [
        (1, hex!("0c60c80f961f0e71f3a9b524af6012062fe037a6")),
        (2, hex!("ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957")),
        (4096, hex!("4b007901b765489abead49d926f721d065a429c1")),
    ] {
        let mut result = [0; 20];
        pbkdf2::pbkdf2_hmac::<sha1::Sha1>(b"password", b"salt", iterations, &mut result);
        assert_eq!(result, expected);
    }
    // SHA512 password/salt vectors; an independently published Wycheproof case follows below.
    assert_eq!(pbkdf2_sha512(b"password", b"salt", 1), hex!("867f70cf1ade02cff3752599a3a53dc4af34c7a669815ae5d513554e1c8cf252 c02d470a285a0501bad999bfe943c08f050235d7d68b1da55e63f73b60a57fce"));
    assert_eq!(pbkdf2_sha512(b"password", b"salt", 2), hex!("e1d9c16aa681708a45f5c7c4e215ceb66e011a2e9f0040713f18aefdb866d53 cf76cab2868a39b9f7840edce4fef5a82be67335c77a6068e04112754f27ccf4e"));
    assert_eq!(pbkdf2_sha512(b"password", b"salt", 0), [0; 64]);
}

#[test]
fn fips197_aes_all_key_sizes() {
    let plain = hex!("00112233445566778899aabbccddeeff");
    macro_rules! check {
        ($cipher:ty, $key:expr, $ciphertext:expr) => {{
            let aes = <$cipher>::new_from_slice(&$key).unwrap();
            let mut block = plain.into();
            aes.encrypt_block(&mut block);
            assert_eq!(&block[..], $ciphertext);
            aes.decrypt_block(&mut block);
            assert_eq!(&block[..], plain);
        }};
    }
    check!(
        aes::Aes128,
        hex!("000102030405060708090a0b0c0d0e0f"),
        hex!("69c4e0d86a7b0430d8cdb78070b4c55a")
    );
    check!(
        aes::Aes192,
        hex!("000102030405060708090a0b0c0d0e0f1011121314151617"),
        hex!("dda97ca4864cdfe06eaf70a0ec0d7191")
    );
    check!(
        aes::Aes256,
        hex!("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"),
        hex!("8ea2b7ca516745bfeafc49904b496089")
    );
}

#[test]
fn sp800_38a_aes256_ctr_partial_calls() {
    let key = hex!("603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4");
    let iv = hex!("f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff");
    let mut data = hex!("6bc1bee22e409f96e93d7e117393172a ae2d8a571e03ac9c9eb76fac45af8e51 30c81c46a35ce411e5fbc1191a0a52ef f69f2445df4f9b17ad2b417be66c3710");
    let expected = hex!("601ec313775789a5b7a7f504bbf3d228 f443e3ca4d62b59aca84e990cacaf5c5 2b0930daa23de94ce87017ba2d84988d dfc9c58db67aada613c2dd08457941a6");
    let mut cipher = ctr::Ctr128BE::<aes::Aes256>::new(&key.into(), &iv.into());
    for chunk in data.chunks_mut(7) {
        cipher.apply_keystream(chunk);
    }
    assert_eq!(data, expected);
}

#[test]
fn openssl_ige_published_vector() {
    // B. Laurie, OpenSSL IGE test vector 1 (also in RustCrypto ige tests).
    use aes::cipher::{BlockModeDecrypt, BlockModeEncrypt};
    let key = hex!("000102030405060708090a0b0c0d0e0f");
    let iv = hex!("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    let expected = hex!("1a8519a6557be652e9da8e43da4ef4453cf456b4ca488aa383c79c98b34797cb");
    let mut blocks = [Default::default(); 2];
    ige::Encryptor::<aes::Aes128>::new(&key.into(), &iv.into()).encrypt_blocks(&mut blocks);
    assert_eq!(&blocks[0][..], &expected[..16]);
    assert_eq!(&blocks[1][..], &expected[16..]);
    ige::Decryptor::<aes::Aes128>::new(&key.into(), &iv.into()).decrypt_blocks(&mut blocks);
    assert!(blocks.iter().all(|block| block.iter().all(|&b| b == 0)));
}

#[test]
fn wycheproof_pbkdf2_sha512_tc3() {
    // C2SP Wycheproof testvectors_v1/pbkdf2_hmacsha512_test.json, tcId 3.
    // 65 bytes cross a digest block boundary; the wrapper returns the first 64.
    let password = hex!("7439315572766f47");
    let salt = hex!("5d76db9ca0f0bae2");
    let expected = hex!("a5d7f0fe4adc54e2ac5edc54e005827a90cbd46c00b72be68f8fbd1da98c079b98622a69b1ea44c0d94cdae03c339b742d047ac63cac0d9af59786baee4a158080");
    assert_eq!(pbkdf2_sha512(&password, &salt, 4096), &expected[..64]);
    let mut result = [0; 65];
    pbkdf2::pbkdf2_hmac::<sha2::Sha512>(&password, &salt, 4096, &mut result);
    assert_eq!(result, expected);
}
